children.isDisabled:
{{
  !(inpTenantCode.text || "").trim() ||
  !Number.isInteger(Number(inpAssetId.text)) ||
  Number(inpAssetId.text) <= 0 ||
  !selScannerType.selectedOptionValue ||
  !selServiceTier.selectedOptionValue ||
  !selScheduleType.selectedOptionValue ||
  (
    selScheduleType.selectedOptionValue === "CRON" &&
    !(inpScheduleExpression.text || "").trim()
  ) ||
  !(inpScheduleTimezone.text || "").trim() ||
  !(inpReason.text || "").trim() ||
  !(inpProfileName.text || "").trim()
||
(() => {
  const value = (inpScannerParameters.text || "").trim();

  if (!value) return false;

  try {
    const parsed = JSON.parse(value);
    return (
      parsed === null ||
      Array.isArray(parsed) ||
      typeof parsed !== "object"
    );
  } catch (e) {
    return true;
  }
})()
}}

